const getMentorActionPlan = (targetRank, logsCount, cardsCount) => {
  const tasks = [];
  if (targetRank < 500) {
    tasks.push("Aim for >95% accuracy in your weekly grand tests to secure top ranks.");
    tasks.push("Drill 50+ hard flashcards daily to cover edge-case clinical conditions.");
  } else if (targetRank < 2000) {
    tasks.push("Aim for >85% accuracy in custom mock exams and grand tests.");
    tasks.push("Maintain a daily revision cycle of 30+ card reviews to secure your seat.");
  } else {
    tasks.push("Target >75% accuracy rate in subject mock tests to breach the cutoff.");
    tasks.push("Create at least 15 new flashcards for every mock test error.");
  }
  tasks.push("Analyze weekly study hours to balance weaker subjects with rest.");
  return tasks;
};

// --- FIREBASE DAILY USAGE TRACKER ---
// Tracks reads/writes/deletes in sessionStorage keyed by today's date.
// Auto-resets when a new day begins. Used to show quota progress in Settings.
const fbTracker = (() => {
  const getKey = () => 'fbUsage_' + new Date().toISOString().split('T')[0];
  const getUsage = () => {
    try {
      const raw = sessionStorage.getItem(getKey());
      return raw ? JSON.parse(raw) : { reads: 0, writes: 0, deletes: 0 };
    } catch { return { reads: 0, writes: 0, deletes: 0 }; }
  };
  const save = (data) => {
    try { sessionStorage.setItem(getKey(), JSON.stringify(data)); } catch { }
  };
  return {
    read: (n = 1) => { const d = getUsage(); d.reads += n; save(d); },
    write: (n = 1) => { const d = getUsage(); d.writes += n; save(d); },
    delete: (n = 1) => { const d = getUsage(); d.deletes += n; save(d); },
    getUsage,
    reset: () => { try { sessionStorage.removeItem(getKey()); } catch { } }
  };
})();

// =============================================================================
// FSRS-4.5 SPACED REPETITION ENGINE
// =============================================================================
// Implements a faithful approximation of the FSRS-4.5 algorithm.
// Reference: https://github.com/open-spaced-repetition/fsrs4anki/wiki/The-Algorithm
//
// D = Difficulty   [1, 10]  ΓÇö higher means harder to recall
// S = Stability    (days)   ΓÇö days until ~90% retention drops below threshold
// R = Retrievability        ΓÇö probability of correct recall right now
//
// Rating codes (matching our 4-button UI):
//   1 = Again   2 = Hard   3 = Good   4 = Easy
// =============================================================================

const FSRS_W = [
  0.4072,  // w[0]  ΓÇö initial stability for Again
  1.1829,  // w[1]  ΓÇö initial stability for Hard
  3.1262,  // w[2]  ΓÇö initial stability for Good
  15.4722, // w[3]  ΓÇö initial stability for Easy
  7.2102,  // w[4]  ΓÇö initial difficulty base
  0.5316,  // w[5]  ΓÇö initial difficulty sensitivity
  1.0651,  // w[6]  ΓÇö difficulty update rate per rating delta
  0.0589,  // w[7]  ΓÇö mean-reversion strength toward easy baseline
  1.5330,  // w[8]  ΓÇö recall stability growth factor
  0.1544,  // w[9]  ΓÇö recall stability decay with stability
  1.0071,  // w[10] ΓÇö recall bonus from low retrievability
  1.9395,  // w[11] ΓÇö forget-stability coefficient
  0.1100,  // w[12] ΓÇö forget-stability difficulty decay
  0.2900,  // w[13] ΓÇö forget-stability stability growth power
  2.2700,  // w[14] ΓÇö forget-stability retrievability bonus
  0.1500,  // w[15] ΓÇö Hard penalty multiplier applied to recall stability
  2.9898,  // w[16] ΓÇö Easy bonus multiplier applied to recall stability
  0.5100,  // w[17] ΓÇö reserved (short-term stability, future use)
  0.3400,  // w[18] ΓÇö reserved (short-term stability, future use)
];

// Power-forgetting-curve constants ΓÇö fixed by FSRS math so R(S days, S) Γëê 0.9
const FSRS_DECAY = -0.5;
const FSRS_FACTOR = 19 / 81; // Γëê 0.23457

const _fsrsClamp = (v, lo, hi) => Math.min(Math.max(v, lo), hi);

/** R(t, S) = (1 + FACTOR * t / S)^DECAY */
const _fsrsR = (t, S) => Math.pow(1 + FSRS_FACTOR * (t / S), FSRS_DECAY);

/** Initial difficulty for first-review rating r. */
const _fsrsD0 = (r) =>
  _fsrsClamp(FSRS_W[4] - Math.exp(FSRS_W[5] * (r - 1)) + 1, 1, 10);

/** Difficulty after a repeat review: delta then mean-revert to DΓéÇ(Easy). */
const _fsrsUpdateD = (D, rating) => {
  const D0easy = _fsrsD0(4);
  const delta = D - FSRS_W[6] * (rating - 3);
  return _fsrsClamp(FSRS_W[7] * D0easy + (1 - FSRS_W[7]) * delta, 1, 10);
};

/** New stability when the card is recalled (rating 2, 3, or 4). */
const _fsrsRecallS = (D, S, R, rating) => {
  const base = S * (
    Math.exp(FSRS_W[8]) *
    (11 - D) *
    Math.pow(S, -FSRS_W[9]) *
    (Math.exp(FSRS_W[10] * (1 - R)) - 1) + 1
  );
  if (rating === 2) return base * FSRS_W[15]; // Hard penalty
  if (rating === 4) return base * FSRS_W[16]; // Easy bonus
  return base;                                 // Good ΓÇö no multiplier
};

/** New stability when the card is forgotten (rating = 1, Again). */
const _fsrsForgetS = (D, S, R) =>
  FSRS_W[11] *
  Math.pow(D, -FSRS_W[12]) *
  (Math.pow(S + 1, FSRS_W[13]) - 1) *
  Math.exp(FSRS_W[14] * (1 - R));

/** Format a local Date to "YYYY-MM-DD" ΓÇö consistent with the app's date convention. */
const _fsrsDateStr = (date) => {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
};

/**
 * calculateNextFSRSReview(existingData, rating, reviewDateStr?)
 *
 * Pure, side-effect-free function. No React/Firebase imports required.
 *
 * @param {object|null} existingData
 *   Current FSRS fields on the Firestore topic object.
 *   Expected shape: { difficulty, stability, lastReviewDate, reviewCount }
 *   Pass null or omit for brand-new topics (first review).
 *
 * @param {1|2|3|4} rating   Recall quality: 1=Again 2=Hard 3=Good 4=Easy
 *
 * @param {string} [reviewDateStr]
 *   "YYYY-MM-DD" date of the review session. Defaults to today (local time).
 *
 * @returns {{
 *   difficulty:     number,  // Updated D Γêê [1,10], 4 decimal places
 *   stability:      number,  // Updated S (days),   4 decimal places
 *   retrievability: number,  // R at review time Γêê [0,1]
 *   interval:       number,  // Whole days until next review
 *   nextReviewDue:  string,  // "YYYY-MM-DD"
 *   lastReviewDate: string,  // "YYYY-MM-DD" (the review date)
 *   reviewCount:    number,  // Cumulative reviews for this topic
 *   isNew:          boolean, // true if this was the very first review
 * }}
 */
const calculateNextFSRSReview = (existingData, rating, reviewDateStr) => {
  // Parse the review date in local time to avoid UTC-offset surprises
  const reviewDate = new Date(
    reviewDateStr ? `${reviewDateStr}T00:00:00` : new Date().toISOString()
  );
  reviewDate.setHours(0, 0, 0, 0);

  const isNew = !existingData || !existingData.stability;

  let D, S, R, newD, newS;

  if (isNew) {
    // ΓöÇΓöÇ First review: bootstrap from rating directly ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    D = _fsrsD0(rating);
    S = FSRS_W[rating - 1]; // w[0..3] map directly to Again/Hard/Good/Easy
    R = 1.0;                 // Assume full retention at card-creation moment
    newD = D;
    newS = S;
  } else {
    // ΓöÇΓöÇ Subsequent review: evolve D and S from prior state ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    D = existingData.difficulty;
    S = existingData.stability;

    // Elapsed days since last review (for R calculation)
    let elapsed = 0;
    if (existingData.lastReviewDate) {
      const last = new Date(`${existingData.lastReviewDate}T00:00:00`);
      last.setHours(0, 0, 0, 0);
      elapsed = Math.max(
        0,
        Math.round((reviewDate.getTime() - last.getTime()) / 86_400_000)
      );
    }

    R = _fsrsR(elapsed, S);
    newD = _fsrsUpdateD(D, rating);
    newS = rating === 1
      ? 0.1
      : _fsrsRecallS(D, S, R, rating);
  }

  // Stability guard: must be a positive finite number (or baseline minimum on forgot)
  newS = rating === 1 ? 0.1 : Math.max(0.1, isFinite(newS) ? newS : FSRS_W[2]);

  // Interval = S rounded to the nearest day (RΓëê0.9 exactly when t=S).
  // Forces exactly 1 day interval on Forgot rating.
  const interval = rating === 1 ? 1 : Math.max(1, Math.round(newS));

  const nextDate = new Date(reviewDate);
  nextDate.setDate(nextDate.getDate() + interval);

  return {
    difficulty: parseFloat(newD.toFixed(4)),
    stability: parseFloat(newS.toFixed(4)),
    retrievability: parseFloat(R.toFixed(4)),
    interval,
    nextReviewDue: _fsrsDateStr(nextDate),
    lastReviewDate: _fsrsDateStr(reviewDate),
    reviewCount: ((existingData?.reviewCount) || 0) + 1,
    isNew,
  };
};
// =============================================================================
// END FSRS-4.5 ENGINE
// =============================================================================

