  // 3. Receiver (Overlay side)
  useEffect(() => {
    if (!isObsOverlay) return;

    const channel = new BroadcastChannel('auto_anki_obs_channel');

    const handleMessage = (event) => {
      if (!event.data) return;

      if (event.data.type === 'OBS_FULL_SYNC' || event.data.type === 'OBS_STATE_UPDATE') {
        const p = event.data.payload;
        if (p.studySchedule !== undefined) setStudySchedule(p.studySchedule);
        if (p.studyLogs !== undefined) setStudyLogs(p.studyLogs);
        if (p.cards !== undefined) {
          setCards(p.cards);
          setTotalCardCount(p.cards.length);
        }
        if (p.pages !== undefined) {
          setPages(p.pages);
          setPendingPageCount(p.pages.filter(page => page.isPending).length);
        }
        if (p.timerState !== undefined) setTimerState(p.timerState);
        if (p.localTimerTimeLeft !== undefined) setLocalTimerTimeLeft(p.localTimerTimeLeft);
        if (p.localCustomTimerTimeLeft !== undefined) setLocalCustomTimerTimeLeft(p.localCustomTimerTimeLeft);
        if (p.localStopwatchTime !== undefined) setLocalStopwatchTime(p.localStopwatchTime);
        if (p.subjectTrackerData !== undefined) setSubjectTrackerData(p.subjectTrackerData);
        if (p.hierarchy !== undefined) setHierarchy(p.hierarchy);

        if (event.data.type === 'OBS_FULL_SYNC') {
          const todayDate = new Date().toLocaleDateString('en-CA');
          if (p.campSessions) localStorage.setItem(`camp_sessions_${todayDate}`, p.campSessions);
          if (p.campB2B) localStorage.setItem(`camp_bedToBook_${todayDate}`, p.campB2B);
          if (p.campHistory) localStorage.setItem('camp_history', p.campHistory);
          if (p.campTimerHistory) localStorage.setItem('camp_timer_history', p.campTimerHistory);
          if (p.campStudentInfo) localStorage.setItem('camp_student_info', p.campStudentInfo);
          setObsTick(prev => prev + 1);
        }
      }

      if (event.data.type === 'CAMP_STATE_UPDATE') {
        const p = event.data.payload;
        const dateStr = p.selectedDate;
        if (p.campSessions) localStorage.setItem(`camp_sessions_${dateStr}`, p.campSessions);
        if (p.campB2B) localStorage.setItem(`camp_bedToBook_${dateStr}`, p.campB2B);
        if (p.campHistory) localStorage.setItem('camp_history', p.campHistory);
        if (p.campTimerHistory) localStorage.setItem('camp_timer_history', p.campTimerHistory);
        if (p.campStudentInfo) localStorage.setItem('camp_student_info', p.campStudentInfo);
        setObsTick(prev => prev + 1);
      }
    };

    channel.addEventListener('message', handleMessage);
    channel.postMessage({ type: 'REQUEST_OBS_SYNC' });

    return () => {
      channel.removeEventListener('message', handleMessage);
      channel.close();
    };
  }, [isObsOverlay]);

