  const weekDays = useMemo(() => {
    const current = new Date(schedulerSelectedDate + 'T00:00:00');
    if (isNaN(current.getTime())) return [];
    const days = [];
    for (let i = -3; i <= 3; i++) {
      const d = new Date(current);
      d.setDate(current.getDate() + i);
      const dateStr = d.toLocaleDateString('en-CA');
      days.push({
        dateStr,
        dayNum: d.getDate(),
        dayName: d.toLocaleDateString('en-US', { weekday: 'narrow' }),
        isToday: dateStr === todayStr,
        hasTasks: (studySchedule[dateStr]?.tasks?.length || 0) > 0
      });
    }
    return days;
  }, [schedulerSelectedDate, studySchedule, todayStr]);

  const getDaysInMonth = (month, year) => {
    const date = new Date(year, month, 1);
    const days = [];
    const startDayOfWeek = date.getDay();
    for (let i = 0; i < startDayOfWeek; i++) {
      days.push(null);
    }
    while (date.getMonth() === month) {
      days.push(new Date(date));
      date.setDate(date.getDate() + 1);
    }
    return days;
  };

  const adherenceStats = useMemo(() => {
    let totalTasks = 0;
    let completedTasks = 0;
    const now = new Date();
    const currentMin = now.getHours() * 60 + now.getMinutes();

    Object.values(studySchedule).forEach(entry => {
      // Only count tasks planned for dates up to and including today
      if (entry.date && entry.date <= todayStr && entry.tasks && Array.isArray(entry.tasks)) {
        entry.tasks.forEach(t => {
          if (entry.date < todayStr) {
            totalTasks++;
            if (t.completed) completedTasks++;
          } else {
            // For today, only count ended/completed sessions
            const start = parseTimeToMinutes(t.startTime) || 0;
            const end = parseTimeToMinutes(t.endTime || formatMinutesToTime(start + 60)) || 0;
            if (t.completed || (t.startTime && end <= currentMin)) {
              totalTasks++;
              if (t.completed) completedTasks++;
            }
          }
        });
      }
    });

    const rate = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

    const last7Days = [];
    for (let i = 6; i >= 0; i--) {
      const d = new Date();
      d.setDate(now.getDate() - i);
      const dateStr = d.toLocaleDateString('en-CA');
      const entry = studySchedule[dateStr];
      let dayTotal = 0;
      let dayCompleted = 0;
      if (entry && entry.tasks && Array.isArray(entry.tasks)) {
        entry.tasks.forEach(t => {
          if (dateStr < todayStr) {
            dayTotal++;
            if (t.completed) dayCompleted++;
          } else {
            // For today, only count ended/completed sessions
            const start = parseTimeToMinutes(t.startTime) || 0;
            const end = parseTimeToMinutes(t.endTime || formatMinutesToTime(start + 60)) || 0;
            if (t.completed || (t.startTime && end <= currentMin)) {
              dayTotal++;
              if (t.completed) dayCompleted++;
            }
          }
        });
      }
      const dayRate = dayTotal > 0 ? Math.round((dayCompleted / dayTotal) * 100) : 0;
      last7Days.push({
        dateStr,
        dateLabel: d.toLocaleDateString('en-US', { weekday: 'short', month: 'numeric', day: 'numeric' }),
        total: dayTotal,
        completed: dayCompleted,
        rate: dayRate
      });
    }

    const breakdownList = Object.keys(studySchedule)
      .sort()
      .reverse()
      .map(dateStr => {
        const entry = studySchedule[dateStr];
        let dayTotal = 0;
        let dayCompleted = 0;
        if (entry && entry.tasks && Array.isArray(entry.tasks)) {
          entry.tasks.forEach(t => {
            if (dateStr < todayStr) {
              dayTotal++;
              if (t.completed) dayCompleted++;
            } else {
              const start = parseTimeToMinutes(t.startTime) || 0;
              const end = parseTimeToMinutes(t.endTime || formatMinutesToTime(start + 60)) || 0;
              if (t.completed || (t.startTime && end <= currentMin)) {
                dayTotal++;
                if (t.completed) dayCompleted++;
              }
            }
          });
        }
        return {
          dateStr,
          total: dayTotal,
          completed: dayCompleted,
          notes: entry.notes || '',
          tasks: entry.tasks || []
        };
      })
      .filter(item => item.total > 0 || item.notes.trim() !== '');

    return {
      totalTasks,
      completedTasks,
      rate,
      last7Days,
      breakdownList
    };
  }, [studySchedule, todayStr]);

