                                                  {sess.questions > 0 && <span className="text-emerald-600">+{sess.questions} Qs</span>}
                                                  {sess.cards > 0 && <span className="text-blue-600">+{sess.cards} Cds</span>}
                                                  {sess.pages > 0 && <span className="text-indigo-600">+{sess.pages} Pgs</span>}
